class Prov:
    def __init__(self, froms=(), commit=None, by=None, note=None):
        self.froms = list(froms)     # (PATH, HEADING or None), as given
        self.commit, self.by, self.note = commit, by, note

    def given(self):
        return bool(self.froms or self.commit or self.by or self.note)

    def over(self, base):
        """This entry's own provenance over the call's."""
        return Prov(base.froms + self.froms, self.commit or base.commit, self.by or base.by, self.note or base.note)

    @staticmethod
    def parse_line(text):
        """`from: PATH, "HEADING"; commit: HASH; by: WHO; note: WHY` (any of them, note last)."""
        out = Prov()
        for m in re.finditer(r'(?:^|;\s*)(from|commit|by|note):\s*(.*?)(?=;\s*(?:from|commit|by|note):|$)', text.strip()):
            name, value = m.group(1), m.group(2).strip()
            if name == 'note':
                value = text.strip()[m.start(2):].strip()
                out.note = value
                break
            if name == 'from':
                out.froms.append(split_from(value))
            elif name == 'commit':
                out.commit = value.strip('`')
            else:
                out.by = value
        return out


def split_from(text):
    """PATH#HEADING, or PATH, "HEADING", or PATH alone -> (PATH, HEADING or None)."""
    text = text.strip()
    m = re.match(r'`?([^`#,"]+?)`?\s*(?:#\s*(.*)|,\s*["“](.*)["”])?$', text)
    if not m:
        raise RecordError('a from is PATH#HEADING or PATH, "HEADING": %s' % text)
    return m.group(1).strip(), (m.group(2) or m.group(3) or '').strip() or None


class ProvChecker:
    """Resolves a write's provenance once per distinct from and commit."""
    def __init__(self, root):
        self.root = root
        self.cache = {}

    def from_(self, path, heading):
        k = ('from', path, heading)
        if k not in self.cache:
            self.cache[k] = resolve_section(self.root, path, heading)
        return self.cache[k]

    def commit(self, h):
        k = ('commit', h)
        if k not in self.cache:
            if git(self.root, 'rev-parse', '--verify', '--quiet', h + '^{commit}').returncode != 0:
                raise RecordError('%s is not a commit' % h)
            if git(self.root, 'merge-base', '--is-ancestor', h, 'HEAD').returncode != 0:
                raise RecordError('%s is not in the history of HEAD' % h)
            self.cache[k] = git(self.root, 'rev-parse', '--short=9', h).stdout.strip()
        return self.cache[k]

    def line(self, prov, kind, stamp):
        """The provenance line of one block, or raise."""
        if not prov.froms and not (prov.note and prov.note.strip()):
            raise RecordError('no provenance: give --from PATH#HEADING or --note WHY')
        fields = [stamp, kind]
        for path, heading in prov.froms:
            rel, head = self.from_(path, heading)
            fields.append('from `%s`' % rel + (', "%s"' % head if head else ''))
        if prov.commit:
            fields.append('commit `%s`' % self.commit(prov.commit))
        if prov.by:
            fields.append('by ' + one_line(prov.by))
        out = SEP.join(fields)
        if prov.note and prov.note.strip():
            out += ': ' + one_line(prov.note)
        return out


# ---------------------------------------------------------------- the state a write leaves

class State:
    """The record files as a write would leave them: each a list of items, ['text', line]
    or ['entry', key, line]."""
    def __init__(self, store):
        self.store = store
        self.items = {}
        for k in 'FP':
            f = store.files[k]
            by_line = {e.lineno: e for e in f.entries}
            items = []
            for i, ln in enumerate(f.lines):
                e = by_line.get(i + 1)
                items.append(['entry', e.key, ln] if e is not None and e.key else ['text', ln])
            self.items[k] = items
        self.old = {key: (e.line, e.section) for key, e in store.live.items()}

    def find(self, key):
        items = self.items[key[0]]
        for i, it in enumerate(items):
            if it[0] == 'entry' and it[1] == key:
                return i
        return None

    def line(self, key):
        i = self.find(key)
        return self.items[key[0]][i][2] if i is not None else None

    def set_line(self, key, line):
        self.items[key[0]][self.find(key)][2] = line

    def delete(self, key):
        items = self.items[key[0]]
        i = self.find(key)
        del items[i]
        if 0 < i < len(items) and items[i - 1] == ['text', ''] and items[i] == ['text', '']:
            del items[i]

## 4. What the library, the team's tests and the demos meet

A build that logged each refusal of the three checks instead of raising it (scratch, not committed) ran the interpreter suite once. At that stage, `checkForDef` refused every inherited bodiless declaration, on objects and generic instances alike. Besides the rung's own tests, its log named:
- in the library, at load: `NewlineReduction` (`Library/FortressLibrary.fss:3496`) under `AssociativeReduction.simpleJoin(Any,Any)` (`:3116`), and so every program;
- in the library, at instances:
  - `MinMaxReduction`, the same;
  - the QuickCheck generators under `AnyGen.perturb(Any, AnySeededRandomGen)` (`Library/QuickCheck.fss:82`);
  - `MersenneTwisterInit` under `SeededRandomGen.perturbed(Generator[\ZZ32\])` (`Library/Random.fss:126`);
  - `SeededRandomGenWithDistribution` under `seedSize` and `reseed` (`:88`, `:99`);
  - `EmptyIM`, `SingletonIM` and `NodeIM` under `IntMap.genComb` (`Library/IntMap.fss:125`);
- the team's tests: `FileConversion.fss`'s `dnaSequence` under `dna`'s `OPLUS(self, other: dna)` (`ProjectFortress/tests/FileConversion.fss:67`), and `XXXUnimplementedMethod.fss`'s `O` under `T`'s `a(Sub2, Sub1)`;
- the revival's `XXXComprisesLibraryTraitUnlistedExtender.fss`, whose `Value` extends `Number` with no `asFloat`.

The library and every test now load as before, because of two choices (decisions 2 and 3):
- A body at or below the abstract parameter types defines the method. This admits `NewlineReduction`, the QuickCheck generators, `MersenneTwisterInit` and `dnaSequence`.
- Generic objects are not checked. This leaves out `IntMap`'s and `Random`'s generic objects.

The Meet Rule check of generic declarations refused none of the library's 146: the logging build logged "PROBE647made" 146 times per load of a one-file program, all made. The `override` check refused only the rung's tests.

The library defects found this way are rows 667 (`IntMap.genComb`), 668 (`SeededRandomGen`'s `seedSize`, `reseed` and `perturbed`) and 669 (`AnyGen.perturb`), each measured on the old code (section 6). `simpleJoin` is row 628's, which rung G of this batch types at `R`.

The demos (section 6): five now meet the rung's refusals: `BirdCount1z`, `BirdCount2a`, `GenomeUtil1z`, `GenomeUtil2a` and `npbft` (row 670).
